  "Before a large edit or before loading another project, save a backup: open Project Management and download the current project JSON. Loading a project replaces the current map, notes, and export settings.": {
    "zh": "做大范围修改或加载其他项目之前，先备份：打开“项目管理”，下载当前项目 JSON。加载项目会替换当前地图、备注和导出设置。",
    "en": "Before a large edit or before loading another project, save a backup: open Project Management and download the current project JSON. Loading a project replaces the current map, notes, and export settings."
  },
  "Before editing, look at the chips at the top of the map. Mode shows the active tool, View shows the map state you are seeing, and Split shows how many countries have split ownership. If any chip looks wrong, switch to the correct scenario or project first.": {
    "zh": "编辑前，先看地图顶部的状态标签。Mode 表示当前工具，View 表示正在看的地图状态，Split 表示当前场景里有多少分裂归属。任何一项不符合预期时，先切到正确的场景或项目。",
    "en": "Before editing, look at the chips at the top of the map. Mode shows the active tool, View shows the map state you are seeing, and Split shows how many countries have split ownership. If any chip looks wrong, switch to the correct scenario or project first."
  },
  "Before export, make sure Strategic annotations are enabled and no line, label, or counter hides the country you want to show.": {
    "zh": "导出前确认战略标注已开启，并且线条、标签或计数器没有遮住要展示的国家。",
    "en": "Before export, make sure Strategic annotations are enabled and no line, label, or counter hides the country you want to show."
  },
  "Before sending files out, keep one editable project JSON and one exported output from the same reviewed state. This keeps later fixes traceable.": {
    "zh": "发送文件前，保留一份可编辑项目 JSON 和一份来自同一已复查状态的导出产物。这样后续修正有迹可循。",
    "en": "Before sending files out, keep one editable project JSON and one exported output from the same reviewed state. This keeps later fixes traceable."
  },
