  "Keep Strategic annotations enabled when frontlines, operational graphics, or unit counters must appear in the final output.": {
    "zh": "最终输出需要前线、作战图形或单位计数器时，保持战略标注开启。",
    "en": "Keep Strategic annotations enabled when frontlines, operational graphics, or unit counters must appear in the final output."
  },
  "Keep a working reference visible while you line up opacity, scale, and offsets.": {
    "zh": "在排列不透明度、比例和偏移时，保持工作参考可见。",
    "en": "Keep a working reference visible while you line up opacity, scale, and offsets."
  },
  "Keep facility names visible only when the current zoom can carry them cleanly.": {
    "zh": "仅当当前缩放可以清晰地显示设施名称时，才使设施名称可见。",
    "en": "Keep facility names visible only when the current zoom can carry them cleanly."
  },
  "Keep label reveal simple and intentional.": {
    "zh": "保持标签显示简单且有意。",
    "en": "Keep label reveal simple and intentional."
  },
  "Keep local versus reference-only subtype scope and pack state visible during review.": {
    "zh": "在审查期间保持本地子类型范围与仅参考子类型范围和包状态可见。",
    "en": "Keep local versus reference-only subtype scope and pack state visible during review."
  },
  "Keep mineral labels opt-in so dense point fields stay readable.": {
    "zh": "保持矿物标签选择加入，以便密集的点字段保持可读。",
    "en": "Keep mineral labels opt-in so dense point fields stay readable."
  },
  "Keep motorway_link, trunk_link, and primary_link out by default.": {
    "zh": "默认情况下，将 motorway_link、trunk_link 和 Primary_link 保留在外面。",
    "en": "Keep motorway_link, trunk_link, and primary_link out by default."
  },
  "Keep names gated so hub points stay readable over industrial land.": {
    "zh": "保持名称门控，以便工业用地上的枢纽点保持可读性。",
    "en": "Keep names gated so hub points stay readable over industrial land."
  },
  "Keep names opt-in so polygon review stays readable.": {
    "zh": "保持名称选择加入，以便多边形评论保持可读性。",
    "en": "Keep names opt-in so polygon review stays readable."
  },
  "Keep official review data separate from publicly releasable data.": {
    "zh": "官方审阅数据与可公开发布的数据分开显示。",
    "en": "Keep official review data separate from publicly releasable data."
  },
  "Keep one main station per city by default.": {
    "zh": "默认每个城市保留一个主站。",
    "en": "Keep one main station per city by default."
  },
  "Keep only the industrial land types you want to inspect.": {
    "zh": "仅保留您想要检查的工业用地类型。",
    "en": "Keep only the industrial land types you want to inspect."
  },
  "Keep pack scope, visible site count, and source governance visible during review.": {
    "zh": "在审查期间保持包范围、可见站点数量和源治理可见。",
    "en": "Keep pack scope, visible site count, and source governance visible during review."
  },
  "Keep port names gated by the current zoom and importance.": {
    "zh": "按当前缩放和重要性控制港口名称显示。",
    "en": "Keep port names gated by the current zoom and importance."
  },
  "Keep ports inspect-first, but allow aggregate and density views when the official layer becomes crowded.": {
    "zh": "港口默认先按检查视图呈现；当官方图层过密时，允许切换到聚合和密度视图。",
    "en": "Keep ports inspect-first, but allow aggregate and density views when the official layer becomes crowded."
  },
  "Keep reconciliation strict rather than heuristic.": {
    "zh": "保持严格的协调而不是启发式的。",
    "en": "Keep reconciliation strict rather than heuristic."
  },
  "Keep service lines from dominating national views.": {
    "zh": "避免服务线主导全国观点。",
    "en": "Keep service lines from dominating national views."
  },
  "Keep service lines off unless deliberately reviewing them.": {
    "zh": "除非刻意检查，否则请保持服务线路关闭。",
    "en": "Keep service lines off unless deliberately reviewing them."
  },
  "Keep service, residential, and track out of the first pack.": {
    "zh": "将服务、住宅和轨道排除在第一包之外。",
    "en": "Keep service, residential, and track out of the first pack."
  },
  "Keep the active hub scope, visible point count, and pack state visible during review.": {
    "zh": "审阅时保持当前枢纽范围、可见点数量和数据包状态可见。",
    "en": "Keep the active hub scope, visible point count, and pack state visible during review."
  },
  "Keep the active source track, filter scope, and pack state visible during review.": {
    "zh": "在审查期间保持活动源跟踪、过滤器范围和包状态可见。",
    "en": "Keep the active source track, filter scope, and pack state visible during review."
  },
  "Keep the first airport pass deterministic and point-only.": {
    "zh": "保持第一个机场通行证的确定性和仅限点。",
    "en": "Keep the first airport pass deterministic and point-only."
  },
  "Keep the line restrained by default, then opt into labels only when the theater needs annotation.": {
    "zh": "默认情况下保持线条受限制，然后仅在剧院需要注释时才选择添加标签。",
    "en": "Keep the line restrained by default, then opt into labels only when the theater needs annotation."
  },
  "Keep the main visibility controls together so opacity, labels, and capital emphasis read as one layer.": {
    "zh": "把主要可见性控制放在一起，让不透明度、标签和首都强调作为同一层来调。",
    "en": "Keep the main visibility controls together so opacity, labels, and capital emphasis read as one layer."
  },
