  "Use Activate Releasable or Reapply Core Territory in Scenario Actions.": {
    "zh": "请在 Scenario Actions 中使用“激活可释放国”或“重新应用核心领土”。",
    "en": "Use Activate Releasable or Reapply Core Territory in Scenario Actions."
  },
  "Use Activate for focused ownership changes and Scenario Actions for broader rule-driven updates. After each pass, re-check the View and Split chips.": {
    "zh": "小范围归属切换用“激活”，批量或规则化调整用“场景操作”。每轮完成后，再检查视图和拆分状态。",
    "en": "Use Activate for focused ownership changes and Scenario Actions for broader rule-driven updates. After each pass, re-check the View and Split chips."
  },
  "Use Activate or Scenario Actions for map edits, tune Appearance and Transport for readability, then save a project JSON before export.": {
    "zh": "用“激活”或“场景操作”修改地图，用“外观”和“交通”提高可读性，导出前保存项目 JSON。",
    "en": "Use Activate or Scenario Actions for map edits, tune Appearance and Transport for readability, then save a project JSON before export."
  },
  "Use Appearance for map readability and Transport for routes, ports, airports, and network context.": {
    "zh": "用“外观”提高地图可读性，用“交通”展示道路、港口、机场和网络背景。",
    "en": "Use Appearance for map readability and Transport for routes, ports, airports, and network context."
  },
  "Use Country Color for Visual Actions": {
    "zh": "使用国家颜色进行视觉操作",
    "en": "Use Country Color for Visual Actions"
  },
  "Use Download Project to save the current editable state: scenario choice, ownership edits, appearance, transport, strategic annotations, reference alignment values, and export settings.": {
    "zh": "使用“下载项目”保存当前可编辑状态：场景选择、归属修改、外观、交通、战略标注、参考图对齐参数和导出设置。",
    "en": "Use Download Project to save the current editable state: scenario choice, ownership edits, appearance, transport, strategic annotations, reference alignment values, and export settings."
  },
  "Use Frontline after you apply a scenario. This section combines the derived conflict overlay with the project-local strategic workspace for operational lines, graphics, and unit counters.": {
    "zh": "先应用场景，再使用 Frontline。这个区块同时管理 derived conflict overlay 和 project-local strategic workspace，用于 operational lines、graphics 和 unit counters。",
    "en": "Use Frontline after you apply a scenario. This section combines the derived conflict overlay with the project-local strategic workspace for operational lines, graphics, and unit counters."
  },
  "Use Guide for workflow steps and Reference for visual alignment. Both stay in the Project tab so you can check instructions without losing context.": {
    "zh": "用 Guide 查看操作流程，用 Reference 做视觉对位。它们都留在 Project tab 里，这样你可以对照指引而不会丢失当前上下文。",
    "en": "Use Guide for workflow steps and Reference for visual alignment. Both stay in the Project tab so you can check instructions without losing context."
  },
  "Use Layer-based special zones for new edits.": {
    "zh": "新编辑请使用分层特殊区域。",
    "en": "Use Layer-based special zones for new edits."
  },
  "Use Open workbench to choose the output target, format, resolution, layer order, text stacks, and image adjustments. Export creates the final image, per-layer PNG set, or bake pack; it does not replace the editable project JSON.": {
    "zh": "使用“打开工作台”选择输出目标、格式、分辨率、图层顺序、文字堆栈和图像调整。导出会生成最终图片、分层 PNG 或 bake pack；它不会替代可编辑的项目 JSON。",
    "en": "Use Open workbench to choose the output target, format, resolution, layer order, text stacks, and image adjustments. Export creates the final image, per-layer PNG set, or bake pack; it does not replace the editable project JSON."
  },
  "Use Project tools as a publish checklist: save the project, add strategic context, align references, then export.": {
    "zh": "把项目工具当成发布检查清单：先保存项目，再补战略信息、对齐参考图，最后导出。",
    "en": "Use Project tools as a publish checklist: save the project, add strategic context, align references, then export."
  },
